{
  "surface": "tip",
  "scope": {"target_id": "apple-m4-max", "task": "gemm", "dtype": "fp16"},
  "action": "Register --validate on the eval-v2 subparser (or stop asking for it in TASK.md's eval-v2 command).",
  "audience": "developer",
  "needs": "repo_change",
  "evidence": {
    "reproduction": "uv run --directory <repo> python -m tcenv.cli eval-v2 gemm <abs>/x.metal --dtype fp16 --size small --timed --validate --target apple-m4-max",
    "expected": "either an instrumented shader-validation pass before the timed benchmark, or a TASK.md command line that does not mention --validate"
  },
  "rationale": "TASK.md instructs the kernel session to finish with --timed --validate; eval-v2 rejects the flag, so the instructed final check cannot be run at all and the session has to guess whether the outer instrumented pass will accept the kernel."
}

{
  "surface": "tool",
  "scope": {"target_id": "apple-m4-max", "task": "gemm", "dtype": "fp16"},
  "action": "Add a --validate switch to tcenv.cli eval-v2 that runs the instrumented shader validation pass alongside the timed benchmark, since TASK.md instructs every kernel session to append it to its final timed run.",
  "audience": "developer",
  "needs": "repo_change",
  "evidence": {
    "reproduction": "python -m tcenv.cli eval-v2 gemm <kernel> --dtype fp16 --size small --timed --validate --target apple-m4-max",
    "expected": "either the documented flag exists and runs the instrumented pass, or TASK.md stops asking for it"
  },
  "rationale": "The documented self-check command in TASK.md is rejected by argparse before any GPU work, so the session cannot catch out-of-bounds or race instrumentation problems before it exits; r7 filed the same request and it is still missing. The cost is one wasted command per session."
}

{
  "surface": "tip",
  "scope": {"target_id": "apple-m4-max", "task": "relu", "dtype": "fp16"},
  "action": "Make the evaluation report canonicalisable when a correctness case's worst-position got/want is non-finite, and drop --validate from the v2 timed command in the task prompt.",
  "audience": "developer",
  "needs": "repo_change",
  "evidence": {
    "reproduction": "uv run --directory <repo> python -m tcenv.cli eval-v2 relu <workdir>/relu-fp16-small-init.metal --dtype fp16 --size small --quick --target apple-m4-max",
    "expected": "the report prints (status ok, candidate_us, speedup) instead of raising IdentityError; and the --timed variant that TASK.md documents exits 0 rather than 'unrecognized arguments: --validate'"
  },
  "rationale": "relu fp16 small is unpassable through the documented commands: a correct kernel reproduces +inf/nan in correctness.cases[5].worst (the ieee case puts a special at index 0 and worst is taken from argmax of an all-zero error vector), which tcenv.identity.float_text refuses while fingerprinting the result document."
}

