{
  "surface": "tool",
  "scope": {"target_id": "apple-m4-max"},
  "action": "Make `tcenv.cli eval-v2 ... --timed` print one same-window control measurement alongside the candidate (an empty kernel at the candidate's launch shape, or the registered seed kernel measured in the same process), and include its µs in the self-check row.",
  "audience": "developer",
  "needs": "repo_change",
  "evidence": {
    "reproduction": "uv run python -m tcenv.cli eval-v2 gemm_silu KERNEL.metal --dtype fp16 --size small --timed --target apple-m4-max --reps 15   # run the same file twice in separate processes; here 1.973 us then 1.608/1.601/1.608 us",
    "expected": "a per-run control value in the same process, so a 1.5x-scale kernel's A/B does not depend on cross-process window drift"
  },
  "rationale": "The task's own promotion rule ('1.005x and 2 standard errors, using your cv') cannot be evaluated from one self-check row when the same kernel moves 20% between rows; we burn the 20-row/120 s allowance on control arms instead of on improving the kernel."
}

